method count_upper(s: string) returns (count: int)
    requires s != null
    ensures count >= 0
    ensures count == |{ i | 0 <= i < s.Length && i % 2 == 0 && (s[i] == 'A' || s[i] == 'E' || s[i] == 'I' || s[i] == 'O' || s[i] == 'U') }|
{
    count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == |{ j | 0 <= j < i && j % 2 == 0 && (s[j] == 'A' || s[j] == 'E' || s[j] == 'I' || s[j] == 'O' || s[j] == 'U') }|
    {
        if i % 2 == 0 && (s[i] == 'A' || s[i] == 'E' || s[i] == 'I' || s[i] == 'O' || s[i] == 'U') {
            count := count + 1;
        }
        i := i + 1;
    }
}
```

